// Function to calculate the nth Fibonacci number recursively
int fibonacci(int n) {
    // Base cases: If n is 0 or 1, return n directly
    if (n <= 1) {
        return n;
    }

    // If n is greater than 1, calculate the nth Fibonacci number recursively
    else {
