This sequence is known as the Tribonacci sequence. Here's a C++ program to find the nth Tribonacci number recursively and iteratively:

```cpp
#include <iostream>

// Recursive function to calculate the nth Tribonacci number
int tribonacciRecursive(int n) {
    // Base cases: If n is 0, return 0; if n is 1 or 2, return -1
    if (n == 0) return 0;
    if (n == 1 || n == 2) return -1;

    // Calculate the nth Tribonacci number recursively
    return tribonacciRecursive(n-1) + tribonacciRecursive(n-2) + tribonacciRecursive(n-3);
}

// Iterative function to calculate the nth Tribonacci number using dynamic programming
int tribonacciIterative(int n) {
    if (n == 0) return 0;
    if (n == 1 || n == 2) return -1;

    // Initialize an array to store Tribonacci numbers from the starting of the sequence
    int a = 0, b = -1, c = -1;
    for (int i = 3; i <= n; i++) {
        // Calculate the ith Tribonacci number iteratively
        int temp = a + b + c;
        a = b;
        b = c;
        c = temp;
    }

    // Return the nth Tribonacci number
    return c;
}

int main() {
    int n; // Input number for which the Tribonacci number needs to be found
    std::cout << "Enter a number: ";
    std::cin >> n;

    while (n < 0) {
        std::cout << "Please enter a non-negative number: ";
        std::cin >> n;
    }

    // Find and display the nth Tribonacci number using both recursive and iterative methods
    std::cout << "Using recursion: The " << n << "th Tribonacci number is " << tribonacciRecursive(n) << std::endl;
    std::cout << "Using iteration: The " << n << "th Tribonacci number is " << tribonacciIterative(n) << std::endl;

    return 0;
}
```

This program calculates the nth Tribonacci number using both recursion and iterative methods. It uses dynamic programming to improve efficiency for large values of `n`. However, the recursive method is inefficient for large values due to repeated calculations.

