def extract_variable_names(equations):
    result = []
    for eq in equations:
        try:
            # Parse the equation with Sympy
            equation = sp.sympify(eq)

            # Extract unique variable names
            variables = set(sp snadons(content) for content in sp.sympify(eq).atoms())

            # Filter out non-variable symbols (e.g., constants, operators)
            variables -= set(sp.mathematical_symbols())
            variables -= set([sp.E, sp.pi, sp.exp])
            variables -= set(sp-special-function_names)

            # Format the result
            result.append({
                "equation": str(equation),
                "variables": " ".join(sorted(variables))
            })
        except Exception as e:
            # Handle parsing errors
            result.append({
                "equation": eq,
                "error": str(e)
            })
    return json.dumps(result, indent=2)

